        private static string FormatChartAxisLabel(int sec)
        {
            if (sec <= 0) return PT("now");
            if (sec < 60) return $"-{sec}s";
            int m = sec / 60, s = sec % 60;
            return s == 0 ? $"-{m}m" : $"-{m}m{s:D2}";
        }

        private void DrawSingleTempChart(Canvas? canvas, float[] data, WpfColor lineColor,
            float yMin = 20f, float yMax = 100f, string unit = "°", string fmt = "F0",
            float? warnThreshold = null)
        {
            if (canvas == null) return;
            if (!_uiVisibleCached) return;   // window hidden: only the data is recorded
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 2 || h < 2) return;

            double ww = w, hh = h;
            if (_slotDrawn.TryGetValue(canvas, out var prev)
                && prev.idx == _chartIdx && Math.Abs(ww - prev.w) < 1 && Math.Abs(hh - prev.h) < 1) return;
            _slotDrawn[canvas] = (_chartIdx, ww, hh);

            if (yMax <= 0)
            {
                float sanityCeiling = unit switch
                {
                    "MHz" => 12000f,   // no consumer CPU/GPU boosts above ~8-9 GHz
                    "W"   => 1500f,    // no consumer CPU/GPU sustains above ~1000 W
                    "MB"  => 131072f,  // 128 GB VRAM — generous above any current graphics card
                    _     => float.MaxValue,
                };

                float maxVal = float.MinValue;
                int n = Math.Min(_chartIdx, ChartMaxPoints);
                for (int k = 0; k < n; k++)
                {
                    float v = data[(_chartIdx - 1 - k + ChartMaxPoints) % ChartMaxPoints];
                    if (!float.IsNaN(v) && float.IsFinite(v) && v > 0 && v <= sanityCeiling)
                        maxVal = Math.Max(maxVal, v);
                }
                if (maxVal <= float.MinValue) maxVal = 1f;
                yMax = (float)Math.Ceiling(maxVal * 1.25f / 10f) * 10f;
                // Second safety net: even if maxVal somehow escaped the filter above, yMax never exceeds the cap (with a 25% margin).
                if (yMax > sanityCeiling * 1.25f) yMax = sanityCeiling * 1.25f;
                yMin = 0f;
            }
            if (yMax <= yMin || !float.IsFinite(yMax)) yMax = yMin + 1f;

            const double pL = 10, pR = 8, pT = 16, pB = 14;
            double cW = w - pL - pR, cH = h - pT - pB;

            var dv  = new DrawingVisual();
            var dpiInfo = VisualTreeHelper.GetDpi(canvas);
            var dpi = dpiInfo.PixelsPerDip;
            var ft  = _chartTypeface;

            using (var dc = dv.RenderOpen())
            {
                dc.DrawRectangle(new SolidColorBrush(WpfColor.FromArgb(0,0,0,0)), null, new Rect(0,0,w,h));

                // Grid lines WITHOUT text labels — only minimal visual context. The temperature thresholds stay, but dotted and
                // labelled separately below.
                DrawPlotGrid(dc, new Rect(pL, pT, cW, cH), 3, 4);

                for (int i = 0; i <= 4; i++)
                {
                    double x = pL + cW * i / 4.0;
                    int sec = (int)Math.Round(StressChartPoints * (1.0 - i / 4.0));
                    var lbl = new FormattedText(FormatChartAxisLabel(sec),
                        System.Globalization.CultureInfo.InvariantCulture,
                        System.Windows.FlowDirection.LeftToRight, ft, 9, _brLabel, dpi);
                    double lx = i == 4 ? x - lbl.Width - 1 : x - 9;
                    dc.DrawText(lbl, new System.Windows.Point(lx, pT + cH + 2));
                }

                // Stress test zones (CPU = blue, GPU = orange). Three modes, chosen from the chart's context menu
                // (SettingsService.Current.StressMarkMode):
                //   Band   — a thin band under the chart + dotted lines at start/stop (default)
                //   Full   — a coloured zone over the whole height + a label
                //   Subtle — like Full, but much more discreet
                // The test type label also appears in the hover tooltip, in all modes.
                {
                    string markMode = SettingsService.Current.StressMarkMode ?? "Subtle";
                    if (markMode == "Band") markMode = "Subtle"; // a translucent red area marks the test period instead of a bottom band
                    int dispPts = Math.Min(_chartIdx, StressChartPoints);
                    long firstIdx = _chartIdx - dispPts;
                    double XOf(long k) => pL + cW * (double)(StressChartPoints - dispPts + (k - firstIdx)) / (StressChartPoints - 1.0);
                    const double stripH = 4;
                    foreach (var iv in _stressIntervals)
                    {
                        long end = iv.End < 0 ? _chartIdx - 1 : iv.End;
                        if (end < firstIdx || dispPts < 2) continue;
                        double x0 = Math.Clamp(XOf(Math.Max(iv.Start, firstIdx)), pL, pL + cW);
                        double x1 = Math.Clamp(XOf(end), pL, pL + cW);
                        if (x1 - x0 < 1) x1 = x0 + 1;
                        var bandColor = WpfColor.FromRgb(239, 68, 68); // the same red shade as the STRESS badges and the buttons
                        bool startVisible = iv.Start >= firstIdx;
                        bool endVisible   = iv.End >= 0;

                        if (markMode == "Band")
                        {
                            // Band at the bottom, against the X axis; GPU under CPU if both run at once
                            double yStrip = pT + cH - stripH - (iv.Kind == "GPU" ? stripH + 1 : 0);
                            var stripBrush = new SolidColorBrush(WpfColor.FromArgb(200, bandColor.R, bandColor.G, bandColor.B)); stripBrush.Freeze();
                            dc.DrawRoundedRectangle(stripBrush, null, new Rect(x0, yStrip, x1 - x0, stripH), 2, 2);
                            var dashPen = new System.Windows.Media.Pen(new SolidColorBrush(WpfColor.FromArgb(90, bandColor.R, bandColor.G, bandColor.B)), 1)
                            { DashStyle = new System.Windows.Media.DashStyle(new double[] { 3, 3 }, 0) };
                            dashPen.Freeze();
                            if (startVisible) dc.DrawLine(dashPen, new System.Windows.Point(x0 + 0.5, pT), new System.Windows.Point(x0 + 0.5, yStrip));
                            if (endVisible)   dc.DrawLine(dashPen, new System.Windows.Point(x1 - 0.5, pT), new System.Windows.Point(x1 - 0.5, yStrip));
                            continue;
                        }

                        bool subtle = markMode == "Subtle";
                        byte fillA = subtle ? (byte)22 : (byte)40;
                        byte edgeA = subtle ? (byte)55 : (byte)110;
                        byte textA = subtle ? (byte)140 : (byte)200;
                        var bandBrush = new SolidColorBrush(WpfColor.FromArgb(fillA, bandColor.R, bandColor.G, bandColor.B)); bandBrush.Freeze();
                        var edgePen = new System.Windows.Media.Pen(new SolidColorBrush(WpfColor.FromArgb(edgeA, bandColor.R, bandColor.G, bandColor.B)), 1); edgePen.Freeze();
                        dc.DrawRectangle(bandBrush, null, new Rect(x0, pT, x1 - x0, cH));
                        if (startVisible) dc.DrawLine(edgePen, new System.Windows.Point(x0, pT), new System.Windows.Point(x0, pT + cH));
                        if (endVisible)   dc.DrawLine(edgePen, new System.Windows.Point(x1, pT), new System.Windows.Point(x1, pT + cH));
                        if (x1 - x0 >= 44)
                        {
                            var bl = new FormattedText(iv.Kind + " stress", System.Globalization.CultureInfo.InvariantCulture,
                                System.Windows.FlowDirection.LeftToRight, ft, 9,
                                new SolidColorBrush(WpfColor.FromArgb(textA, bandColor.R, bandColor.G, bandColor.B)), dpi);
                            dc.DrawText(bl, new System.Windows.Point(x0 + 4, pT + 1));
                        }
                    }
                }

                const int gapBreakThreshold = 3;
                var runs = new List<List<(double x, double y, float val)>>();
                List<(double x, double y, float val)>? curRun = null;
                int nanStreak = 0;
                int displayPts = Math.Min(_chartIdx, StressChartPoints);
                for (int i = 0; i < displayPts; i++)
                {
                    int idx = (_chartIdx - displayPts + i + ChartMaxPoints * 2) % ChartMaxPoints;
                    float v = data[idx];
                    if (float.IsNaN(v) || v <= 0)
                    {
                        nanStreak++;
                        if (nanStreak >= gapBreakThreshold) curRun = null; // a real gap — a new run after it
                        continue; // an isolated glitch: skip the point, do NOT drop the current segment
                    }
                    nanStreak = 0;
                    double xFrac = (double)(StressChartPoints - displayPts + i) / (StressChartPoints - 1.0);
                    double px = pL + cW * xFrac;
                    double py = pT + cH * (1.0 - Math.Clamp((v - yMin) / (yMax - yMin), 0, 1));
                    if (curRun == null) { curRun = new List<(double x, double y, float val)>(); runs.Add(curRun); }
                    curRun.Add((px, py, v));
                }
                int totalPts = 0; foreach (var r in runs) totalPts += r.Count;
                // "pts" kept as an alias for the last valid segment (used below to position the end dot/label — see after the runs loop).
                var pts = runs.Count > 0 ? runs[^1] : new List<(double x, double y, float val)>();

                if (pts.Count >= 2)
                {
                    WpfColor lineCol = lineColor;

                    // Line — the same smooth path (Catmull-Rom → Bezier), but 2 px instead of 1.5 px
                    var lineGeom = new StreamGeometry();
                    using (var ctx = lineGeom.Open())
                    {
                        ctx.BeginFigure(new System.Windows.Point(pts[0].x, pts[0].y), false, false);
                        for (int i = 1; i < pts.Count; i++)
                        {
                            var p0 = pts[Math.Max(0,i-2)]; var p1 = pts[i-1];
                            var p2 = pts[i]; var p3 = pts[Math.Min(pts.Count-1,i+1)];
                            const double tt = 0.3;
                            var cp1 = new System.Windows.Point(p1.x+(p2.x-p0.x)*tt/3.0, p1.y+(p2.y-p0.y)*tt/3.0);
                            var cp2 = new System.Windows.Point(p2.x-(p3.x-p1.x)*tt/3.0, p2.y-(p3.y-p1.y)*tt/3.0);
                            ctx.BezierTo(cp1, cp2, new System.Windows.Point(p2.x, p2.y), true, false);
                        }
                    }
                    lineGeom.Freeze();

                    var fillClosed = new StreamGeometry();
                    using (var ctx = fillClosed.Open())
                    {
                        ctx.BeginFigure(new System.Windows.Point(pts[0].x, pT + cH), true, true);
                        ctx.LineTo(new System.Windows.Point(pts[0].x, pts[0].y), true, false);
                        const double t = 0.3;
                        for (int i = 1; i < pts.Count; i++)
                        {
                            var p0 = pts[Math.Max(0, i-2)]; var p1 = pts[i-1];
                            var p2 = pts[i]; var p3 = pts[Math.Min(pts.Count-1, i+1)];
                            var cp1 = new System.Windows.Point(p1.x+(p2.x-p0.x)*t/3.0, p1.y+(p2.y-p0.y)*t/3.0);
                            var cp2 = new System.Windows.Point(p2.x-(p3.x-p1.x)*t/3.0, p2.y-(p3.y-p1.y)*t/3.0);
                            ctx.BezierTo(cp1, cp2, new System.Windows.Point(p2.x, p2.y), true, false);
                        }
                        ctx.LineTo(new System.Windows.Point(pts[^1].x, pT+cH), true, false);
                    }
                    fillClosed.Freeze();
                    var fillBr = new System.Windows.Media.LinearGradientBrush(
                        WpfColor.FromArgb(60, lineCol.R, lineCol.G, lineCol.B),
                        WpfColor.FromArgb(4,  lineCol.R, lineCol.G, lineCol.B),
                        new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
                    fillBr.Freeze();
                    dc.DrawGeometry(fillBr, null, fillClosed);

                    var linePen = GetCachedLinePen(lineCol, 2.0, roundJoin: true);
                    dc.DrawGeometry(null, linePen, lineGeom);

                    var tipBr = new SolidColorBrush(lineCol); tipBr.Freeze();
                    dc.DrawEllipse(tipBr, null, new System.Windows.Point(pts[^1].x, pts[^1].y), 3.5, 3.5);
                }
                else
                {
                    var noData = new FormattedText("Waiting for data…",
                        System.Globalization.CultureInfo.InvariantCulture,
                        System.Windows.FlowDirection.LeftToRight, ft, 10, _brLabel, dpi);
                    dc.DrawText(noData, new System.Windows.Point(pL + cW / 2 - 45, pT + cH / 2 - 7));
                }
            }

            var overlays = new List<System.Windows.UIElement>();
            foreach (System.Windows.UIElement child in canvas.Children)
            {
                if (child is System.Windows.Shapes.Line || child is System.Windows.Controls.Border)
                    overlays.Add(child);
            }

            RenderToCanvas(canvas, dv, w, h);

            foreach (var overlay in overlays)
            {
                try
                {
                    if (System.Windows.Media.VisualTreeHelper.GetParent(overlay) == null)
                        canvas.Children.Add(overlay);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            if (canvas.Children.Count > 0 && canvas.Children[0] is System.Windows.Controls.Image baseImg)
                baseImg.IsHitTestVisible = false;
        }

        /// <summary>Draw CPU frequency history chart.</summary>
        private void DrawCpuFreqChart() => DrawCpuFreqChart(null);
        private void DrawCpuFreqChart(System.Windows.Controls.Canvas? targetCanvas)
        {
            var canvas = targetCanvas
                         ?? (FindName("CpuFreqCanvas") as System.Windows.Controls.Canvas)
                         ?? CpuFreqChart;
            if (canvas == null) return;
            if (!_uiVisibleCached) return;   // window hidden: only the data is recorded
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 2 || h < 2) return;
            if (_chartIdx == _drawnIdxCpuFreq && Math.Abs(w - _drawnWCpuFreq) < 1 && Math.Abs(h - _drawnHCpuFreq) < 1) return;
            _drawnIdxCpuFreq = _chartIdx; _drawnWCpuFreq = w; _drawnHCpuFreq = h;

            float maxFreq = _chartCpuFreq.Max();
            if (maxFreq < 500) maxFreq = 5000;
            float yMax = (float)(Math.Ceiling(maxFreq * ChartScale.Headroom / 1000.0) * 1000);   // peak + 10%: the curve never touches the top

            double pL = 30, pR = 6, pT = 8, pB = 14;
            double cW = w - pL - pR, cH = h - pT - pB;

            var dv  = new DrawingVisual();
            var dpiInfo2 = VisualTreeHelper.GetDpi(canvas);
            var dpi = dpiInfo2.PixelsPerDip;
            var dpiScale2 = dpiInfo2.DpiScaleX;
            var ft  = _chartTypeface;
            var lineColor = WpfColor.FromRgb(96, 165, 250);
            var pen = new System.Windows.Media.Pen(new SolidColorBrush(lineColor), 1.5)
                { LineJoin = System.Windows.Media.PenLineJoin.Round };

            using (var dc = dv.RenderOpen())
            {
                dc.DrawRectangle(_brBgRect, null, new Rect(0, 0, w, h));

                DrawPlotGrid(dc, new Rect(pL, pT, cW, cH), 3);   // the shared grid; its rows match the 0 / ⅓ / ⅔ / max labels
                for (int step = 0; step <= 3; step++)
                {
                    float val = yMax * step / 3f;
                    double y = pT + cH * (1.0 - val / yMax);
                    var lbl = new FormattedText($"{val/1000:F1}G",
                        System.Globalization.CultureInfo.InvariantCulture,
                        System.Windows.FlowDirection.LeftToRight, ft, 10, _brLabel, dpi);
                    double ly = y - lbl.Height / 2;
                    if (ly < -1) ly = -1;
                    if (ly > pT + cH - lbl.Height + 1) ly = pT + cH - lbl.Height + 1;
                    dc.DrawText(lbl, new System.Windows.Point(1, ly));
                }
                dc.DrawLine(_penAxis, new System.Windows.Point(pL, pT), new System.Windows.Point(pL, pT + cH));

                var pts = _reusePoints; pts.Clear();
                int availFreqPts = Math.Min(_chartIdx, ChartPoints);
                for (int i = 0; i < availFreqPts; i++)
                {
                    int idx = (_chartIdx - availFreqPts + i + ChartMaxPoints * 2) % ChartMaxPoints;
                    float v = _chartCpuFreq[idx];
                    if (float.IsNaN(v) || v <= 0)
                    {
                        if (pts.Count >= 2) DrawFreqSegment(dc, pts, pT, cH, yMax, lineColor);
                        pts.Clear();
                        continue;
                    }
                    double xFrac = (double)(ChartPoints - availFreqPts + i) / (ChartPoints - 1.0);
                    pts.Add((pL + cW * xFrac,
                             pT + cH * (1.0 - Math.Clamp(v / yMax, 0, 1))));
                }
                // Draw final segment
                if (pts.Count >= 2) DrawFreqSegment(dc, pts, pT, cH, yMax, lineColor);
            }

            RenderToCanvas(canvas, dv, w, h);
        }

        /// <summary>Draw a single continuous segment of the CPU freq chart (fill + line + dot).</summary>
        private static void DrawFreqSegment(System.Windows.Media.DrawingContext dc,
            List<(double x, double y)> pts, double pT, double cH, float yMax, WpfColor lineColor)
        {
            if (pts.Count < 2) return;
            var pen = new System.Windows.Media.Pen(
                new SolidColorBrush(lineColor), 1.5)
                { LineJoin = System.Windows.Media.PenLineJoin.Round };
            pen.Freeze();

            // Fill area
            var fillG = new StreamGeometry();
            using (var ctx = fillG.Open())
            {
                ctx.BeginFigure(new System.Windows.Point(pts[0].x, pts[0].y), true, true);
                foreach (var (px, py) in pts.Skip(1)) ctx.LineTo(new System.Windows.Point(px, py), true, false);
                ctx.LineTo(new System.Windows.Point(pts[^1].x, pT + cH), true, false);
                ctx.LineTo(new System.Windows.Point(pts[0].x,  pT + cH), true, false);
            }
            fillG.Freeze();
            var freqFillBr = new System.Windows.Media.LinearGradientBrush(
                WpfColor.FromArgb(50, lineColor.R, lineColor.G, lineColor.B),
                WpfColor.FromArgb( 5, lineColor.R, lineColor.G, lineColor.B),
                new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
            freqFillBr.Freeze();
            dc.DrawGeometry(freqFillBr, null, fillG);

            // Line
            var lineG = new StreamGeometry();
            using (var ctx = lineG.Open())
            {
                ctx.BeginFigure(new System.Windows.Point(pts[0].x, pts[0].y), false, false);
                foreach (var (px, py) in pts.Skip(1)) ctx.LineTo(new System.Windows.Point(px, py), true, false);
            }
            lineG.Freeze();
            dc.DrawGeometry(null, pen, lineG);

            // Dot at latest point — solid, no outline, 3.5px (unified)
            var freqDotBr = new SolidColorBrush(lineColor); freqDotBr.Freeze();
            dc.DrawEllipse(freqDotBr, null,
                new System.Windows.Point(pts[^1].x, pts[^1].y), 3.5, 3.5);
        }


        private void DrawCpuUsageChart()
        {
            var canvas = (FindName("CpuUsageCanvas") as System.Windows.Controls.Canvas)
                         ?? CpuUsageChart;
            if (canvas == null) return;
            if (!_uiVisibleCached) return;   // window hidden: only the data is recorded
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 2 || h < 2) return;
            if (_chartIdx == _drawnIdxCpuUsage && Math.Abs(w - _drawnWCpuUsage) < 1 && Math.Abs(h - _drawnHCpuUsage) < 1) return;
            _drawnIdxCpuUsage = _chartIdx; _drawnWCpuUsage = w; _drawnHCpuUsage = h;

            if (!_dvCache.TryGetValue(canvas, out var dv))
            {
                dv = new DrawingVisual();
                _dvCache[canvas] = dv;
            }
            var dpiInfo = VisualTreeHelper.GetDpi(canvas);
            double dpi = dpiInfo.PixelsPerDip;
            double dpiScale = dpiInfo.DpiScaleX;

            double pL = 30, pR = 6, pT = 4, pB = 14;
            double cW = w - pL - pR, cH = h - pT - pB;
            var lineColor = WpfColor.FromRgb(34, 197, 94); // green

            using (var dc = dv.RenderOpen())
            {
                dc.DrawRectangle(_brBgRect, null, new Rect(0, 0, w, h));

                bool veryShort = cH < 95;
                DrawPlotGrid(dc, new Rect(pL, pT, cW, cH), 4);   // the shared grid; its rows match the 25 % steps
                for (int step = 0; step <= 4; step++)
                {
                    double val = step * 25.0;
                    double y = pT + cH * (1.0 - val / 100.0);
                    bool showLabel = veryShort ? (step == 0 || step == 4) : (step % 2 == 0);
                    if (!showLabel) continue;
                    var lbl = (_ftPct.Length > step) ? _ftPct[step]
                        : new FormattedText($"{val:F0}%", System.Globalization.CultureInfo.InvariantCulture,
                            System.Windows.FlowDirection.LeftToRight, _chartTypeface, 10, _brLabel, dpi);
                    double ly = y - 10;
                    if (ly < pT) ly = pT;                       // 100% does not go past the edge
                    if (ly > pT + cH - 9) ly = pT + cH - 9;     // 0% does not go below the chart
                    dc.DrawText(lbl, new System.Windows.Point(1, ly));
                }
                dc.DrawLine(_penAxis, new System.Windows.Point(pL, pT), new System.Windows.Point(pL, pT + cH));

                // Build points
                var pts = _reusePoints; pts.Clear();
                int availUsagePts = Math.Min(_chartIdx, ChartPoints);
                for (int i = 0; i < availUsagePts; i++)
                {
                    int idx2 = (_chartIdx - availUsagePts + i + ChartMaxPoints * 2) % ChartMaxPoints;
                    float v = _chartCpuUsage[idx2];
                    if (float.IsNaN(v) || v < 0) { if (pts.Count >= 2) DrawUsageSegment(dc, pts, pT, cH, lineColor); pts.Clear(); continue; }
                    double xFrac = (double)(ChartPoints - availUsagePts + i) / (ChartPoints - 1.0);
                    pts.Add((pL + cW * xFrac, pT + cH * (1.0 - Math.Clamp(v / 100.0, 0, 1))));
                }
                if (pts.Count >= 2) DrawUsageSegment(dc, pts, pT, cH, lineColor);
            }

            RenderToCanvas(canvas, dv, w, h);
        }

        private static void DrawUsageSegment(System.Windows.Media.DrawingContext dc,
            List<(double x, double y)> pts, double pT, double cH, WpfColor lineColor)
        {
            if (pts.Count < 2) return;
            var pen = new System.Windows.Media.Pen(new SolidColorBrush(lineColor), 1.5)
                { LineJoin = System.Windows.Media.PenLineJoin.Round };

            // Fill
            var fillG = new StreamGeometry();
            using (var ctx = fillG.Open())
            {
                ctx.BeginFigure(new System.Windows.Point(pts[0].x, pts[0].y), true, true);
                foreach (var (px, py) in pts.Skip(1)) ctx.LineTo(new System.Windows.Point(px, py), true, false);
                ctx.LineTo(new System.Windows.Point(pts[^1].x, pT + cH), true, false);
                ctx.LineTo(new System.Windows.Point(pts[0].x,  pT + cH), true, false);
            }
            fillG.Freeze();
            var fillBr = new System.Windows.Media.LinearGradientBrush(
                WpfColor.FromArgb(55, lineColor.R, lineColor.G, lineColor.B),
                WpfColor.FromArgb(5,  lineColor.R, lineColor.G, lineColor.B),
                new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
            fillBr.Freeze();
            dc.DrawGeometry(fillBr, null, fillG);

            // Line
            var lineG = new StreamGeometry();
            using (var ctx = lineG.Open())
            {
                ctx.BeginFigure(new System.Windows.Point(pts[0].x, pts[0].y), false, false);
                foreach (var (px, py) in pts.Skip(1)) ctx.LineTo(new System.Windows.Point(px, py), true, false);
            }
            lineG.Freeze();
            dc.DrawGeometry(null, pen, lineG);

            // Dot
            var dotBr = new SolidColorBrush(lineColor); dotBr.Freeze();
            dc.DrawEllipse(dotBr, null, new System.Windows.Point(pts[^1].x, pts[^1].y), 3.5, 3.5);
        }

        private System.Windows.Media.Pen _penDashPingDynamic = MakeChartPen(34, 197, 94, 2.0);

        private void StartDashboardBackgroundPing()
        {
            // the Ping monitor already writes to the same history: a second writer would double the rate and spoil the average
            if (_pingRunning) return;
            _dashPingCts?.Cancel();
            _dashPingCts?.Dispose();
            _dashPingCts = new CancellationTokenSource();
            var token = _dashPingCts.Token;
            string host = PingHostCurrent;
            if (FindName("TxtDashPingHost") is TextBlock pht) pht.Text = host;

            _ = Task.Run(async () =>
            {
                while (!token.IsCancellationRequested)
                {
                    float ms = float.NaN;
                    try
                    {
                        // A new Ping object on every iteration — avoids hanging after a few pings
                        using var p = new System.Net.NetworkInformation.Ping();
                        var reply = await p.SendPingAsync(host, 2000);
                        NetworkSelfTraffic.ReportPingBytes(outBytes: 60,
                            inBytes: reply.Status == System.Net.NetworkInformation.IPStatus.Success ? 60 : 0);
                        if (reply.Status == System.Net.NetworkInformation.IPStatus.Success)
                            ms = (float)reply.RoundtripTime;
                    }
                    catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* timeout or no network — ms stays NaN */ }

                    _dashPingHasRunOnce = true;
                    _dashLastPingFailed = float.IsNaN(ms);

                    // Scriere atomica a indexului — evita race condition cu UI thread
                    int idx = System.Threading.Interlocked.Increment(ref _pingHistIdx) - 1;
                    _pingTimeTicks[idx % _pingTimeTicks.Length] = DateTime.Now.Ticks;
                    _pingHistory[idx % _pingHistory.Length] = ms;

                    try { await Task.Delay(1000, token); } catch (OperationCanceledException) { break; }
                }
            }, token);
        }

        private readonly Dictionary<System.Windows.Controls.Canvas, System.Windows.Controls.Image> _chartImages = new();
        private readonly Dictionary<System.Windows.Controls.Canvas, DrawingVisual> _dvCache = new();
        private readonly Dictionary<uint, System.Windows.Media.SolidColorBrush> _dotBrushCache = new();
        private readonly Dictionary<uint, System.Windows.Media.LinearGradientBrush> _fillBrushCache = new();
        private readonly Dictionary<uint, System.Windows.Media.Pen> _linePenCache = new();
        private System.Windows.Media.Pen GetCachedLinePen(WpfColor color, double thickness, bool roundJoin = false)
        {
            uint key = (((uint)color.R << 16) | ((uint)color.G << 8) | color.B)
                       ^ ((uint)(thickness * 10) << 24) ^ (roundJoin ? 0x80000000u : 0u);
            if (!_linePenCache.TryGetValue(key, out var pen))
            {
                var br = new SolidColorBrush(color); br.Freeze();
                pen = new System.Windows.Media.Pen(br, thickness);
                if (roundJoin) pen.LineJoin = System.Windows.Media.PenLineJoin.Round;
                pen.Freeze();
                _linePenCache[key] = pen;
            }
            return pen;
        }
        private readonly Dictionary<uint, System.Windows.Media.LinearGradientBrush> _fillBrushCacheFlat = new();
        private readonly Dictionary<string, System.Windows.Media.FormattedText> _ftLabelCache = new();

        // ── DrawingVisualHost: a child that shows a DrawingVisual without taking part in WPF layout ──
        // Unlike Image (which computes DesiredSize from the DrawingImage and may return NaN), DrawingVisualHost always returns
        // Size(0,0) as DesiredSize and does not take part in layout.
        private sealed class DrawingVisualHost : System.Windows.FrameworkElement
        {
            private DrawingVisual? _dv;
            public DrawingVisualHost(DrawingVisual dv) { _dv = dv; AddVisualChild(_dv); AddLogicalChild(_dv); }
            public DrawingVisual? Visual => _dv;
            public void Detach()
            {
                if (_dv != null) { RemoveVisualChild(_dv); RemoveLogicalChild(_dv); _dv = null; }
            }
            public void Swap(DrawingVisual newDv)
            {
                if (ReferenceEquals(_dv, newDv)) return;
                Detach();
                _dv = newDv;
                AddVisualChild(_dv); AddLogicalChild(_dv);
                InvalidateVisual();
            }
            protected override int VisualChildrenCount => _dv != null ? 1 : 0;
            protected override System.Windows.Media.Visual GetVisualChild(int index) => _dv!;
            protected override System.Windows.Size MeasureOverride(System.Windows.Size availableSize)
                => System.Windows.Size.Empty; // NEVER NaN
            protected override System.Windows.Size ArrangeOverride(System.Windows.Size finalSize)
                => finalSize;
        }

        private void RenderToCanvas(System.Windows.Controls.Canvas canvas, DrawingVisual dv, double w, double h)
        {
            if (canvas == null) return;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 1 || h < 1) return;

            try
            {
                if (!_chartHosts.TryGetValue(canvas, out var existingHost) || existingHost == null)
                {
                    // First time: create a new host
                    var host = new DrawingVisualHost(dv);
                    host.Width  = w;
                    host.Height = h;
                    System.Windows.Controls.Canvas.SetLeft(host, 0);
                    System.Windows.Controls.Canvas.SetTop(host, 0);
                    canvas.Children.Clear();
                    canvas.Children.Add(host);
                    _chartImages[canvas] = null!;
                    _chartHosts[canvas]  = host;
                    canvas.SizeChanged -= OnChartCanvasSizeChanged;
                    canvas.SizeChanged += OnChartCanvasSizeChanged;
                }
                else
                {
                    if (existingHost.Visual == dv)
                    {
                        double nw = canvas.ActualWidth  > 0 ? canvas.ActualWidth  : w;
                        double nh = canvas.ActualHeight > 0 ? canvas.ActualHeight : h;
                        if (Math.Abs(existingHost.Width - nw) > 0.5)  existingHost.Width  = nw;
                        if (Math.Abs(existingHost.Height - nh) > 0.5) existingHost.Height = nh;
                    }
                    else
                    {
                        // DV recreated (theme change → _dvCache.Clear) — swap on the existing host
                        existingHost.Swap(dv);
                        existingHost.Width  = canvas.ActualWidth  > 0 ? canvas.ActualWidth  : w;
                        existingHost.Height = canvas.ActualHeight > 0 ? canvas.ActualHeight : h;
                    }
                }
            }
            catch (Exception ex) { AppLogger.Debug($"RenderToCanvas: {ex.Message}"); }
        }
        private readonly System.Collections.Generic.Dictionary<System.Windows.Controls.Canvas,
            DrawingVisualHost> _chartHosts = new();

        private void OnChartCanvasSizeChanged(object sender, System.Windows.SizeChangedEventArgs e)
        {
            if (sender is not System.Windows.Controls.Canvas canvas) return;
            if (!double.IsFinite(e.NewSize.Width) || !double.IsFinite(e.NewSize.Height)) return;
            if (e.NewSize.Width < 1 || e.NewSize.Height < 1) return;
            if (_chartHosts.TryGetValue(canvas, out var host))
            {
                host.Width  = e.NewSize.Width;
                host.Height = e.NewSize.Height;
                _dvCache.Remove(canvas);
            }
        }

