        private SMDWin.Services.TempSnapshot? _lastTempSnapRaw;
        private SMDWin.Services.TempSnapshot? _lastTempSnapBlank;
        // Maximum age at which a snapshot is still shown as "live" (updated on every tick).
        private TimeSpan _sensorLiveMaxAge = TimeSpan.FromSeconds(30);
        private bool _sensorDataStale;

        /// <summary>
        /// The snapshot used by ALL displays. If the last real read is older than _sensorLiveMaxAge (stuck sensor, LHM timeout),
        /// it returns a copy WITHOUT measured values — the UI shows "—", the charts have a gap, alerts do not work on old data.
        /// </summary>
        private SMDWin.Services.TempSnapshot? _lastTempSnap
        {
            get
            {
                var raw = _lastTempSnapRaw;
                if (raw == null) return null;
                if (raw.IsFresh(_sensorLiveMaxAge)) return raw;
                var blank = _lastTempSnapBlank;
                if (blank == null || blank.CapturedUtc != raw.CapturedUtc)
                    _lastTempSnapBlank = blank = raw.WithoutMeasurements();
                return blank;
            }
        }
