        private static WpfColor LerpColor(WpfColor a, WpfColor b, double t)
        {
            t = Math.Clamp(t, 0, 1);
            return WpfColor.FromRgb(
                (byte)(a.R + (b.R - a.R) * t),
                (byte)(a.G + (b.G - a.G) * t),
                (byte)(a.B + (b.B - a.B) * t));
        }

        private static WpfColor GradientTempColor(float t)
        {
            // Stops: <50 light blue → 50-60 blue-grey → 60-70 warm grey →
            // 70-80 subtle orange → 80-90 orange → 90+ red.
            (float Temp, WpfColor Color)[] stops =
            {
                (40f, WpfColor.FromRgb(0x62, 0xA0, 0xEA)), // light blue
                (55f, WpfColor.FromRgb(0x6E, 0x8C, 0xA0)), // albastru-gri
                (65f, WpfColor.FromRgb(0x8C, 0x86, 0x82)), // gri cald neutru
                (75f, WpfColor.FromRgb(0xB4, 0x8C, 0x64)), // subtle orange
                (85f, WpfColor.FromRgb(0xD2, 0x78, 0x3C)), // orange
                (95f, WpfColor.FromRgb(0xDC, 0x3C, 0x3C)), // red
            };
            if (t <= stops[0].Temp) return stops[0].Color;
            if (t >= stops[^1].Temp) return stops[^1].Color;
            for (int i = 0; i < stops.Length - 1; i++)
            {
                if (t >= stops[i].Temp && t <= stops[i + 1].Temp)
                {
                    double frac = (t - stops[i].Temp) / (stops[i + 1].Temp - stops[i].Temp);
                    return LerpColor(stops[i].Color, stops[i + 1].Color, frac);
                }
            }
            return stops[^1].Color;
        }

        private static WpfColor GradientPercentColor(float pct)
        {
            // The same idea for percentage metrics (Load/RAM): green → amber → red, interpolated continuously, not bands with an
            // abrupt threshold.
            (float Pct, WpfColor Color)[] stops =
            {
                (0f,   WpfColor.FromRgb(0x62, 0xA0, 0xEA)), // light blue (calm, the same as temperature)
                (50f,  WpfColor.FromRgb(0x7C, 0x9A, 0x7E)), // neutral green-grey
                (70f,  WpfColor.FromRgb(0xB4, 0x8C, 0x64)), // subtle orange
                (85f,  WpfColor.FromRgb(0xD2, 0x78, 0x3C)), // orange
                (95f,  WpfColor.FromRgb(0xDC, 0x3C, 0x3C)), // red
            };
            if (pct <= stops[0].Pct) return stops[0].Color;
            if (pct >= stops[^1].Pct) return stops[^1].Color;
            for (int i = 0; i < stops.Length - 1; i++)
            {
                if (pct >= stops[i].Pct && pct <= stops[i + 1].Pct)
                {
                    double frac = (pct - stops[i].Pct) / (stops[i + 1].Pct - stops[i].Pct);
                    return LerpColor(stops[i].Color, stops[i + 1].Color, frac);
                }
            }
            return stops[^1].Color;
        }

        private static WpfColor TempColorGradient(float t, bool isGpu = false)
        {
            if (isGpu)
                return t > 85f ? WpfColor.FromRgb(239, 68, 68)   // hot — red
                     : t > 50f ? WpfColor.FromRgb(245, 158, 11)  // warm — amber
                     :           WpfColor.FromRgb(56, 138, 221); // cool — albastru
            return t > 75f ? WpfColor.FromRgb(239, 68, 68)       // hot/critical — red
                 : t > 60f ? WpfColor.FromRgb(245, 158, 11)      // warm — amber
                 :           WpfColor.FromRgb(56, 138, 221);     // cool — albastru
        }

        private FormattedText MakeFt(string text, double dpi) =>
